package io.jnative.processor;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.Objects;

/** One generated file with origin / fingerprint identity. */
public final class GeneratedArtifact {
    public enum Kind {
        SOURCE,
        RESOURCE,
        METADATA
    }

    private final Kind kind;
    private final String relativePath;
    private final String content;
    private final String processorName;
    private final String processorVersion;
    private final String originSource;
    private final String originSymbol;
    private final String inputFingerprint;

    public GeneratedArtifact(
            Kind kind,
            String relativePath,
            String content,
            String processorName,
            String processorVersion,
            String originSource,
            String originSymbol,
            String inputFingerprint
    ) {
        this.kind = kind;
        this.relativePath = relativePath;
        this.content = content == null ? "" : content;
        this.processorName = processorName;
        this.processorVersion = processorVersion;
        this.originSource = originSource == null ? "" : originSource;
        this.originSymbol = originSymbol == null ? "" : originSymbol;
        this.inputFingerprint = inputFingerprint == null ? "" : inputFingerprint;
    }

    public Kind kind() {
        return kind;
    }

    public String relativePath() {
        return relativePath;
    }

    public String content() {
        return content;
    }

    public String processorName() {
        return processorName;
    }

    public String processorVersion() {
        return processorVersion;
    }

    public String originSource() {
        return originSource;
    }

    public String originSymbol() {
        return originSymbol;
    }

    public String inputFingerprint() {
        return inputFingerprint;
    }

    public String outputHash() {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] dig = md.digest(content.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(dig);
        } catch (Exception e) {
            return Integer.toHexString(Objects.hashCode(content));
        }
    }

    public String headerComment() {
        return "// generated by: " + processorName + " " + processorVersion + "\n"
                + "// origin: " + originSource
                + (originSymbol.isEmpty() ? "" : " (" + originSymbol + ")") + "\n"
                + "// fingerprint: " + inputFingerprint + "\n"
                + "// Metaprogramming LLVM intrinsics: NONE\n";
    }
}
